"use client";
import { Alert, AlertTitle, AlertDescription, AlertAction } from "@ui/alert";
import { useRef, useState } from "react";
import { Button } from "@ui/button";
import { Card, CardFooter, CardHeader } from "@ui/card";
import { InlineNotice, InlineNoticeAction, InlineNoticeContent } from "@ui/inline-notice";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@ui/select";
import { Skeleton } from "@ui/skeleton";
import { TabItem, TabPanel, Tabs, TabsList } from "@ui/tabs";
import { Tooltip } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { projectMonitorLabels, validTimestamp } from "./project-monitor-data";
import { MonitorPanel, OverviewView, ReportsView, StorageView } from "./project-monitor-views";
import type { ProjectMonitorProps, ProjectMonitorTab } from "./project-monitor-types";
/** 项目切换重置本地视图与复制反馈，受控值仍由宿主负责。 */
export function ProjectMonitor(props: ProjectMonitorProps) {
    return <ProjectMonitorContent key={props.data.project.id} {...props}/>;
}
function ProjectMonitorContent({ data, tab, defaultTab = "overview", onTabChange, range, defaultRange, onRangeChange, state = "ready", refreshing = false, retainDataOnError = false, statusMessage, actions, advisor, visibleSections, labels: suppliedLabels, locale = "zh-CN", timeZone = "Asia/Shanghai", className, ...props }: ProjectMonitorProps) {
    const labels = { ...projectMonitorLabels, ...suppliedLabels };
    const [localTab, setLocalTab] = useState<ProjectMonitorTab>(defaultTab);
    const [localRange, setLocalRange] = useState(defaultRange ?? data.windows[0]?.id);
    const [copyFeedback, setCopyFeedback] = useState<{
        endpoint: string;
        message: string;
    } | null>(null);
    const copying = useRef(false);
    const Copy = useIcon("copy");
    const Settings = useIcon("settings");
    const Clock = useIcon("clock");
    const Refresh = useIcon("rotate-ccw");
    const hasAdvisor = advisor !== undefined && advisor !== null;
    const tabs: ProjectMonitorTab[] = hasAdvisor ? ["overview", "storage", "reports", "advisor"] : ["overview", "storage", "reports"];
    const requestedTab = tab ?? localTab;
    const activeTab = tabs.includes(requestedTab) ? requestedTab : "overview";
    const requestedRange = range ?? localRange;
    const selectedWindow = data.windows.find((window) => window.id === requestedRange) ?? (range === undefined ? data.windows[0] : undefined);
    const loading = state === "loading";
    const [pending, setPending] = useState<"refresh" | "retry" | null>(null);
    const inFlight = useRef(false);
    const [actionError, setActionError] = useState<{
        data: typeof data;
        message: string;
    } | null>(null);
    const currentError = actionError?.data === data ? actionError.message : undefined;
    const busy = loading || refreshing || pending !== null;
    const failed = state === "error" || currentError !== undefined;
    const replacesData = state === "error" && !retainDataOnError;
    async function runAction(kind: "refresh" | "retry") {
        const callback = kind === "refresh" ? actions?.onRefresh : actions?.onRetry;
        if (!callback || inFlight.current || loading || refreshing)
            return;
        inFlight.current = true;
        setPending(kind);
        setActionError(null);
        try {
            await callback();
        }
        catch (cause) {
            setActionError({ data, message: cause instanceof Error && cause.message ? cause.message : labels.error });
        }
        finally {
            inFlight.current = false;
            setPending(null);
        }
    }
    const retryAction = actions?.onRetry ? <Button variant="secondary" disabled={busy} loading={pending === "retry"} onClick={() => void runAction("retry")}>{labels.retry}</Button> : undefined;
    const date = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", timeZone });
    const updated = validTimestamp(data.updatedAt) ? date.format(data.updatedAt) : labels.unknown;
    async function copyEndpoint() {
        if (copying.current)
            return;
        copying.current = true;
        const endpoint = data.project.endpoint;
        try {
            await navigator.clipboard.writeText(endpoint);
            setCopyFeedback({ endpoint, message: labels.copied });
        }
        catch {
            setCopyFeedback({ endpoint, message: labels.copyError });
        }
        finally {
            copying.current = false;
        }
    }
    const rangeControl = data.windows.length > 0 ? <Select value={selectedWindow?.id ?? ""} onValueChange={(id) => {
            if (range === undefined)
                setLocalRange(id);
            onRangeChange?.(id);
        }} size="sm" disabled={loading}>
    <SelectTrigger aria-label={labels.range} wrapperClassName="max-w-full"/>
    <SelectContent>{data.windows.map((window) => <SelectItem key={window.id} value={window.id} label={window.label}>{window.label}</SelectItem>)}</SelectContent>
  </Select> : null;
    const viewProps = { data, labels, locale, timeZone };
    return <Card {...props} aria-busy={busy || undefined} data-slot="project-monitor" data-state={state} className={cn("@container w-full max-w-3xl overflow-hidden rounded-2xl bg-surface-raised pb-0", className)}>
    <CardHeader className="flex flex-row flex-wrap items-center justify-between gap-4 px-5 py-5">
      <div className="min-w-0 flex-1 basis-44">
        <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1"><h2 className="min-w-0 max-w-full break-words text-title font-semibold text-fg-default">{data.project.name}</h2><span className="min-w-0 max-w-full break-words text-label text-fg-subtle">{data.project.region}</span></div>
        <div className="mt-1 flex min-w-0 items-center gap-1"><span className="min-w-0 break-all font-mono text-label text-fg-muted">{data.project.endpoint}</span><Tooltip content={labels.copy}><Button aria-label={labels.copy} iconOnly size="xs" variant="ghost" onClick={copyEndpoint} disabled={!data.project.endpoint}><Copy /></Button></Tooltip></div>
        <p role="status" className="text-label text-fg-muted">{copyFeedback?.endpoint === data.project.endpoint ? copyFeedback.message : null}</p>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {actions?.onRefresh && <Button aria-label={labels.refresh ?? "刷新数据"} iconOnly size="sm" variant="tertiary" disabled={busy} loading={refreshing || pending === "refresh"} onClick={() => void runAction("refresh")}><Refresh /></Button>}
        {actions?.onOpenDashboard && <Button onClick={actions.onOpenDashboard}>{labels.openDashboard}</Button>}
      </div>
    </CardHeader>
    <Tabs value={activeTab} onValueChange={(value) => {
            if (!tabs.includes(value as ProjectMonitorTab))
                return;
            if (tab === undefined)
                setLocalTab(value as ProjectMonitorTab);
            onTabChange?.(value as ProjectMonitorTab);
        }} variant="pill" color="neutral" className="min-w-0">
      <TabsList aria-label={labels.navigation} className="mx-3 mb-2">{tabs.map((item) => <TabItem key={item} value={item} label={labels[item]}/>)}</TabsList>
      <div className="mx-1">
        {state === "stale" && !failed && <div className="mb-1"><InlineNotice variant="emphasized" tone="warning"><InlineNoticeContent>{statusMessage ?? labels.stale}</InlineNoticeContent></InlineNotice></div>}
        {!loading && !replacesData && busy && <div className="mb-1"><InlineNotice variant="emphasized" tone="info"><span aria-hidden="true" className="inline-flex h-5 shrink-0 items-center [&_svg]:size-4"><span className="inline-flex animate-spin motion-reduce:animate-none"><Refresh /></span></span><InlineNoticeContent>{labels.refreshing ?? "正在刷新，保留上次获取的结果。"}</InlineNoticeContent></InlineNotice></div>}
        {!replacesData && failed && <div className="mb-1"><InlineNotice variant="emphasized" tone="danger" role={currentError ? "alert" : undefined}><InlineNoticeContent>{currentError ?? statusMessage ?? labels.error} {labels.previousData ?? "当前显示上次获取的结果。"}</InlineNoticeContent>{retryAction && <InlineNoticeAction>{retryAction}</InlineNoticeAction>}</InlineNotice></div>}
        {loading ? <TabPanel value={activeTab}><MonitorPanel><div role="status" className="space-y-5"><span className="sr-only">{labels.loading}</span><Skeleton className="h-8 w-36"/><Skeleton className="h-40 w-full"/><Skeleton className="h-24 w-full"/></div></MonitorPanel></TabPanel>
            : replacesData ? <TabPanel value={activeTab}><MonitorPanel><div className="flex min-w-0 w-full items-center justify-center min-h-60 px-4 py-8"><Alert status="danger" role={Boolean(currentError) ? "alert" : "group"} className="w-full max-w-xl"><AlertTitle>{labels.error}</AlertTitle><AlertDescription>{currentError ?? statusMessage}</AlertDescription><AlertAction>{retryAction}</AlertAction></Alert></div></MonitorPanel></TabPanel>
                : <>
              <TabPanel value="overview"><OverviewView {...viewProps} window={selectedWindow} rangeControl={rangeControl} visibleSections={visibleSections}/></TabPanel>
              <TabPanel value="storage"><StorageView {...viewProps}/></TabPanel>
              <TabPanel value="reports"><ReportsView window={selectedWindow} labels={labels} locale={locale} timeZone={timeZone} rangeControl={rangeControl}/></TabPanel>
              {hasAdvisor && <TabPanel value="advisor"><MonitorPanel>{advisor}</MonitorPanel></TabPanel>}
            </>}
      </div>
    </Tabs>
    <CardFooter className="flex-wrap justify-between gap-3 px-5 py-4">
      <p className="flex items-center gap-2 text-label text-fg-subtle"><Clock size={14}/><span>{labels.updated} {updated}</span></p>
      {actions?.onCustomize && <Button variant="tertiary" size="sm" leadingIcon={Settings} onClick={actions.onCustomize}>{labels.customize}</Button>}
    </CardFooter>
  </Card>;
}

"use client";
import type { ReactNode } from "react";
import { Badge } from "@ui/badge";
import { Empty, EmptyDescription } from "@ui/empty";
import { InfoItem, InfoItemContent, InfoItemDescription, InfoItemGroup, InfoItemLeading, InfoItemTitle, InfoItemTrailing, InfoItemValue } from "@ui/info-item";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { StatusOverview } from "@ui/status-overview";
import { useIcon, type IconName } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { StorageUsage } from "@components/blocks/storage-usage-01";
import { bucketTotal, formatBytes, formatMetric, summarizeWindow, validNumber, validTimestamp } from "./project-monitor-data";
import { LatencyChart, RequestTrend, ResourceMetric, ServiceDistribution } from "./project-monitor-charts";
import type { ProjectMonitorData, ProjectMonitorLabels, ProjectMonitorProps, ProjectMonitorWindow } from "./project-monitor-types";
export function MonitorPanel({ children, className, label }: {
    children: ReactNode;
    className?: string;
    label?: string;
}) {
    return <section aria-label={label} className={cn("rounded-xl border-hairline border-border bg-surface-floating p-5", className)}>{children}</section>;
}
export function NoMonitorData({ children }: {
    children: ReactNode;
}) {
    return <Empty reason="no-data" scope="inline" density="compact"><EmptyDescription>{children}</EmptyDescription></Empty>;
}
function MissingWindow({ labels, rangeControl }: {
    labels: ProjectMonitorLabels;
    rangeControl: ReactNode;
}) {
    return <MonitorPanel>
    {rangeControl && <div className="mb-5 flex justify-end">{rangeControl}</div>}
    <NoMonitorData>{labels.noData}</NoMonitorData>
  </MonitorPanel>;
}
function ProjectFact({ label, value, icon = "square-library" }: {
    label: string;
    value: ReactNode;
    icon?: IconName;
}) {
    const Icon = useIcon(icon);
    return <InfoItem className="px-0"><InfoItemLeading><Icon /></InfoItemLeading><InfoItemContent><InfoItemDescription>{label}</InfoItemDescription><InfoItemTitle className="break-words">{value}</InfoItemTitle></InfoItemContent></InfoItem>;
}
interface ViewProps {
    data: ProjectMonitorData;
    labels: ProjectMonitorLabels;
    locale: string;
    timeZone: string;
}
interface WindowProps {
    window: ProjectMonitorWindow;
    labels: ProjectMonitorLabels;
    locale: string;
    timeZone: string;
    rangeControl: ReactNode;
}
export function RequestSummary({ window, labels, locale, rangeControl, peak = false }: Omit<WindowProps, "timeZone"> & {
    peak?: boolean;
}) {
    const summary = summarizeWindow(window);
    return <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
    <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1"><strong data-slot="project-request-total" className="text-heading font-semibold tabular-nums text-fg-default">{formatMetric(summary.total, locale, 0)}</strong><span className="text-label text-fg-subtle">{labels.requests}{peak && ` · ${labels.peak} ${formatMetric(summary.peak, locale, 0)}`}</span></div>
    {rangeControl}
  </div>;
}
function ServiceActivity({ window, labels, locale, timeZone, rangeControl }: WindowProps) {
    const summary = summarizeWindow(window);
    const time = new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit", timeZone });
    return <MonitorPanel label={labels.activity}>
    <RequestSummary window={window} labels={labels} locale={locale} rangeControl={rangeControl}/>
    {!summary.complete && <InlineNotice variant="emphasized" tone="warning"><InlineNoticeContent>{labels.incomplete}</InlineNoticeContent></InlineNotice>}
    <div className="space-y-4">
      {summary.services.map((service) => <StatusOverview key={service.id} variant="activity" ariaLabel={`${service.name} · ${labels.activity}`} label={service.name} summary={{ label: labels.requests, value: formatMetric(service.total, locale, 0) }} emptyContent={labels.noData} content={{ type: "timeline", start: window.start, end: window.end, items: service.buckets.map((bucket, index) => {
                    const total = bucketTotal(bucket);
                    const status = total === null ? "unknown" : total === 0 ? "empty" : bucket!.errors > 0 ? "down" : bucket!.warning > 0 ? "degraded" : "operational";
                    const duration = (window.end - window.start) / service.buckets.length;
                    const timestamp = window.start + duration * index;
                    const at = validTimestamp(timestamp) ? time.format(timestamp) : labels.unknown;
                    const periodId = validTimestamp(timestamp) ? `${timestamp}-${duration}` : `unknown-${index}`;
                    return { id: `${service.id}-${window.id}-${periodId}`, status, ariaLabel: `${service.name}，${at}，${total === null ? labels.noData : `${formatMetric(total, locale, 0)} ${labels.requests}；${labels.success} ${bucket!.success}，${labels.warning} ${bucket!.warning}，${labels.errors} ${bucket!.errors}`}` };
                }) }}/>)}
    </div>
    {summary.complete && <div className="mt-5 flex flex-wrap justify-center gap-x-5 gap-y-2">
      {([["success", "success"], ["warning", "warning"], ["errors", "danger"]] as const).map(([key, status]) => <Badge key={key} variant="dot" status={status}>{labels[key]} · {summary.total ? new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(summary.totals[key] / summary.total) : "—"}</Badge>)}
    </div>}
  </MonitorPanel>;
}
export function OverviewView({ data, labels, locale, timeZone, window, rangeControl, visibleSections }: ViewProps & {
    window?: ProjectMonitorWindow;
    rangeControl: ReactNode;
    visibleSections: ProjectMonitorProps["visibleSections"];
}) {
    const health = data.project.health;
    const status = { healthy: "success", degraded: "warning", down: "danger", unknown: "neutral" } as const;
    return <div className="space-y-1">
    <MonitorPanel>
      <div className="grid gap-x-8 @md:grid-cols-2">
        <ProjectFact label={labels.health} icon="shield" value={<Badge variant="dot" status={status[health]}>{health === "unknown" ? labels.unknownHealth : labels[health]}</Badge>}/>
        {data.project.facts.map((fact) => <ProjectFact key={fact.id} label={fact.label} value={fact.value ?? labels.unknown} icon={fact.icon}/>)}
      </div>
    </MonitorPanel>
    {visibleSections?.resources !== false && <MonitorPanel label={labels.resources}>
      {data.metrics.length ? <div className="grid grid-cols-2 gap-x-5 gap-y-6 @md:grid-cols-3 @2xl:grid-cols-5">{data.metrics.map((metric) => <ResourceMetric key={metric.id} metric={metric} locale={locale}/>)}</div> : <NoMonitorData>{labels.noData}</NoMonitorData>}
    </MonitorPanel>}
    {visibleSections?.activity !== false && (window ? <ServiceActivity window={window} labels={labels} locale={locale} timeZone={timeZone} rangeControl={rangeControl}/> : <MissingWindow labels={labels} rangeControl={rangeControl}/>)}
  </div>;
}
export function StorageView({ data, labels, locale, timeZone }: ViewProps) {
    const Folder = useIcon("folder");
    const Globe = useIcon("globe");
    const Lock = useIcon("lock");
    const { storage } = data;
    const available = validNumber(storage.capacityBytes) && storage.categories.every((category) => validNumber(category.bytes));
    const date = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", timeZone });
    return <div className="space-y-1">
    {available ? <StorageUsage className="rounded-xl border-hairline border-border bg-surface-floating p-5" label={labels.storageUsage} unit="GB" locale={locale} data={{ capacity: storage.capacityBytes! / 1e9, items: storage.categories.map((category) => ({ id: category.id, label: category.label, value: category.bytes! / 1e9, color: category.color })) }} formatters={{ usageSummary: (used, capacity, unit) => `已用 ${used} ${unit} / 共 ${capacity} ${unit}`, remaining: (remaining, unit) => `剩余 ${remaining} ${unit}` }}/>
            : <MonitorPanel label={labels.storageUsage}><NoMonitorData>{labels.noData}</NoMonitorData></MonitorPanel>}
    <InfoItemGroup aria-label={labels.buckets} className="border-hairline border-border p-2">
      {storage.buckets.length ? storage.buckets.map((bucket) => <InfoItem key={bucket.id} className="flex-wrap gap-y-2 py-4">
        <InfoItemLeading><Folder /></InfoItemLeading>
        <InfoItemContent><InfoItemTitle className="break-words">{bucket.name}</InfoItemTitle><InfoItemDescription className="flex flex-wrap items-center gap-1.5">{bucket.access === "public" ? <Globe size={12}/> : <Lock size={12}/>}{bucket.access === "public" ? labels.public : labels.private} · {formatMetric(bucket.files, locale, 0)} {labels.files}</InfoItemDescription></InfoItemContent>
        <InfoItemTrailing><div className="space-y-1"><InfoItemValue>{formatBytes(bucket.bytes, locale)}</InfoItemValue><p className="text-label text-fg-subtle">{validTimestamp(bucket.updatedAt) ? date.format(bucket.updatedAt) : labels.unknown}</p></div></InfoItemTrailing>
      </InfoItem>) : <NoMonitorData>{labels.noData}</NoMonitorData>}
    </InfoItemGroup>
  </div>;
}
export function ReportsView({ window, labels, locale, timeZone, rangeControl }: Omit<WindowProps, "window"> & {
    window?: ProjectMonitorWindow;
}) {
    if (!window)
        return <MissingWindow labels={labels} rangeControl={rangeControl}/>;
    const summary = summarizeWindow(window);
    return <div className="space-y-1">
    <MonitorPanel>
      <RequestSummary window={window} labels={labels} locale={locale} rangeControl={rangeControl} peak/>
      {!summary.complete && <InlineNotice variant="emphasized" tone="warning"><InlineNoticeContent>{labels.incomplete}</InlineNoticeContent></InlineNotice>}
      {summary.points.length ? <RequestTrend window={window} labels={labels} locale={locale} timeZone={timeZone}/> : <NoMonitorData>{labels.noData}</NoMonitorData>}
    </MonitorPanel>
    <MonitorPanel><div className="grid gap-8 @2xl:grid-cols-2"><ServiceDistribution window={window} labels={labels} locale={locale}/><LatencyChart window={window} labels={labels} locale={locale}/></div></MonitorPanel>
  </div>;
}

"use client";
import { Bar, BarChart, XAxis, YAxis } from "recharts";
import { badgeColors } from "@ui/badge";
import { ChartContainer, DonutSummary, TimeSeriesChart } from "@ui/chart";
import { ChartLegend, chartSeriesColor, createChartNumberFormatter } from "@ui/chart-primitives";
import { MetricCard } from "@ui/metric-card";
import { formatMetric, summarizeWindow, validNumber } from "./project-monitor-data";
import type { ProjectMonitorLabels, ProjectMonitorMetric, ProjectMonitorWindow } from "./project-monitor-types";
export function ResourceMetric({ metric, locale }: {
    metric: ProjectMonitorMetric;
    locale: string;
}) {
    const hasCapacity = validNumber(metric.capacity) && metric.capacity > 0;
    const available = validNumber(metric.value);
    const percentage = hasCapacity && available ? Math.min(1, metric.value! / metric.capacity!) : null;
    const value = formatMetric(metric.value, locale);
    if (!hasCapacity)
        return <MetricCard label={metric.label} value={value} unit={metric.unit} state={available ? "ready" : "unavailable"} statusMessage={available ? undefined : "暂无可用数据"} className="h-full justify-center border-0 bg-transparent p-0 text-center"/>;
    const text = metric.unit === "%" ? `${value}%` : `${value}/${formatMetric(metric.capacity, locale)}`;
    return <figure className="min-w-0 text-center" aria-label={`${metric.label}：${text}`}>
    <DonutSummary className="mx-auto w-24" segments={[{ id: "used", label: metric.label, value: percentage, color: "var(--brand)" }]} total={1} innerRadius="83%" aria-label={`${metric.label}：${text}`} center={<span className="text-body font-semibold">{text}</span>}/>
    <figcaption className="mt-3 text-label text-fg-subtle">{metric.label}</figcaption>
  </figure>;
}
export function RequestTrend({ window, labels, locale, timeZone }: {
    window: ProjectMonitorWindow;
    labels: ProjectMonitorLabels;
    locale: string;
    timeZone: string;
}) {
    const { points } = summarizeWindow(window);
    return <TimeSeriesChart data={points.map((point) => ({ timestamp: point.timestamp, values: { requests: point.requests } }))} series={[{ id: "requests", label: labels.requests, color: "var(--brand)" }]} domain={[window.start, window.end]} locale={locale} timeZone={timeZone} label={`${window.label} · ${labels.requests}，缺失时段保留断点`} dataSummary="查看数据"/>;
}
export function ServiceDistribution({ window, labels, locale }: {
    window: ProjectMonitorWindow;
    labels: ProjectMonitorLabels;
    locale: string;
}) {
    const { services, total, complete } = summarizeWindow(window);
    const segments = services.map((service) => ({ id: service.id, label: service.name, value: service.total, color: badgeColors[service.color] }));
    const formatPercent = createChartNumberFormatter(locale, { style: "percent", maximumFractionDigits: 1 });
    return <div className="min-w-0">
    <h3 className="mb-5 text-label font-medium text-fg-subtle">{labels.serviceDistribution}</h3>
    <div className="flex flex-col items-center gap-5 @sm:flex-row">
      <DonutSummary className="w-32 shrink-0" segments={segments} total={total} aria-label={`${labels.total}：${formatMetric(total, locale, 0)}${complete ? "" : ` · ${labels.incomplete}`}`} center={<><strong className="text-body font-semibold">{formatMetric(total, locale, 0)}</strong><span className="text-label text-fg-subtle">{labels.requests}</span></>}/>
      <ChartLegend className="w-full @sm:w-auto @sm:flex-1" items={segments.map((service) => ({ ...service, value: formatMetric(service.value, locale, 0), ratio: complete && total! > 0 ? formatPercent(service.value! / total!) : "—" }))}/>
    </div>
    {!complete && <p className="mt-3 text-label text-fg-subtle">{labels.incomplete}</p>}
  </div>;
}
export function LatencyChart({ window, labels, locale }: {
    window: ProjectMonitorWindow;
    labels: ProjectMonitorLabels;
    locale: string;
}) {
    const entries = [{ key: "p50", label: "P50", color: chartSeriesColor("p50") }, { key: "p95", label: "P95", color: chartSeriesColor("p95") }, { key: "p99", label: "P99", color: chartSeriesColor("p99") }] as const;
    // 超过约定标尺仍显示真实值，所有分位数始终共用一个标尺。
    const maximum = Math.max(validNumber(window.latencyScaleMs) ? window.latencyScaleMs : 0, ...entries.map(({ key }) => validNumber(window.latency[key]) ? window.latency[key]! : 0), 1);
    return <div className="min-w-0">
    <h3 className="mb-5 text-label font-medium text-fg-subtle">{labels.latency} · {window.label}</h3>
    <div className="space-y-3">
      {entries.map(({ key, label, color }) => <div key={key}>
        <div className="flex items-center justify-between gap-3 text-label"><span className="text-fg-subtle">{label}</span><span className="tabular-nums text-fg-default">{formatMetric(window.latency[key], locale, 0)} {labels.milliseconds}</span></div>
        <ChartContainer aria-hidden="true" config={{ value: { color } }} className="h-5 min-h-0">
          <BarChart layout="vertical" data={[{ value: validNumber(window.latency[key]) ? window.latency[key] : 0 }]} margin={{ top: 0, right: 0, bottom: 0, left: 0 }} accessibilityLayer={false}>
            <XAxis type="number" domain={[0, maximum]} hide/><YAxis type="category" hide/>
            <Bar dataKey="value" fill="var(--color-value)" background={{ fill: "var(--muted)" }} barSize={5} radius={3} isAnimationActive={false}/>
          </BarChart>
        </ChartContainer>
      </div>)}
    </div>
  </div>;
}

import type { ComponentPropsWithoutRef, ReactNode } from "react";
import type { BadgeColor } from "@ui/badge";
import type { IconName } from "@lib/icon-context";
export type ProjectMonitorTab = "overview" | "storage" | "reports" | "advisor";
export type ProjectMonitorState = "ready" | "loading" | "stale" | "error";
export interface ProjectMonitorMetric {
    id: string;
    label: string;
    /** value 和 capacity 使用相同单位；未知值为 null，不能用零代替。 */
    value: number | null;
    capacity?: number | null;
    unit: string;
}
export interface ProjectMonitorBucket {
    id: string;
    name: string;
    access: "public" | "private";
    files: number | null;
    bytes: number | null;
    updatedAt: number | null;
}
export interface ProjectMonitorService {
    id: string;
    name: string;
    color: BadgeColor;
    /** 每一项对应时间窗口内连续、等长的一个时间桶。null 表示未收到数据。 */
